ALTER TABLE public.account_deletion_requests ADD COLUMN IF NOT EXISTS processing_history jsonb NOT NULL DEFAULT '[]';
CREATE OR REPLACE FUNCTION public.deletion_is_held(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.account_deletion_requests WHERE user_id=_user AND processing_state IN ('processing','failed','completed') AND (scope='account' OR processing_state<>'completed')); $$;
REVOKE ALL ON FUNCTION public.deletion_is_held(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.deletion_is_held(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.deletion_has_retained_dependencies(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user AND role<>'patient') OR EXISTS(SELECT 1 FROM public.appointments WHERE patient_id=_user) OR EXISTS(SELECT 1 FROM public.case_records WHERE patient_id=_user) OR EXISTS(SELECT 1 FROM public.prescriptions WHERE patient_id=_user OR doctor_id=_user) OR EXISTS(SELECT 1 FROM public.case_clinical_notes WHERE doctor_id=_user) OR EXISTS(SELECT 1 FROM public.orders WHERE user_id=_user) OR EXISTS(SELECT 1 FROM public.payments WHERE user_id=_user OR recorded_by=_user) OR EXISTS(SELECT 1 FROM public.prescription_audit WHERE actor_id=_user OR patient_id=_user) OR EXISTS(SELECT 1 FROM public.clinical_assignments WHERE doctor_id=_user OR assigned_by=_user); $$;
REVOKE ALL ON FUNCTION public.deletion_has_retained_dependencies(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.deletion_has_retained_dependencies(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.claim_account_deletion(_request uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE r public.account_deletion_requests%ROWTYPE; ticket uuid; uid uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator required'; END IF; SELECT user_id INTO STRICT uid FROM public.account_deletion_requests WHERE id=_request; PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,4917)); SELECT * INTO STRICT r FROM public.account_deletion_requests WHERE id=_request FOR UPDATE; IF r.processing_state='completed' THEN RETURN jsonb_build_object('state','completed'); END IF; IF r.processing_state IN ('processing','failed') THEN RAISE EXCEPTION 'Deletion already processing or failed; reconcile before retry'; END IF; IF public.deletion_has_retained_dependencies(r.user_id) THEN UPDATE public.account_deletion_requests SET processing_state='blocked',failure_code='retention_review_required' WHERE id=r.id; RETURN jsonb_build_object('state','blocked'); END IF; ticket:=gen_random_uuid(); UPDATE public.account_deletion_requests SET processing_state='processing',processing_token=ticket,failure_code=NULL WHERE id=r.id; RETURN jsonb_build_object('state','processing','token',ticket,'user_id',r.user_id,'scope',r.scope); END; $$;
CREATE OR REPLACE FUNCTION public.purge_eligible_account_data(_request uuid,_token uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE r public.account_deletion_requests%ROWTYPE; uid uuid; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service required'; END IF; SELECT user_id INTO STRICT uid FROM public.account_deletion_requests WHERE id=_request; PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,4917)); SELECT * INTO STRICT r FROM public.account_deletion_requests WHERE id=_request AND processing_token=_token AND processing_state='processing' FOR UPDATE; IF public.deletion_has_retained_dependencies(r.user_id) THEN RAISE EXCEPTION 'Retention review required'; END IF; DELETE FROM public.health_consent_receipts WHERE user_id=r.user_id; DELETE FROM public.checkout_requests WHERE user_id=r.user_id; DELETE FROM public.gateway_initiations WHERE user_id=r.user_id; DELETE FROM public.clinical_assignments WHERE patient_id=r.user_id; IF r.scope='account' THEN DELETE FROM public.profiles WHERE id=r.user_id; DELETE FROM public.user_roles WHERE user_id=r.user_id; ELSE UPDATE public.profiles SET full_name='',phone=NULL,date_of_birth=NULL,gender=NULL,city=NULL,avatar_url=NULL WHERE id=r.user_id; END IF; END; $$;
CREATE OR REPLACE FUNCTION public.guard_deletion_dependencies() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE doc jsonb:=to_jsonb(NEW); key text; uid uuid; BEGIN FOR key IN SELECT unnest(ARRAY['patient_id','user_id','doctor_id','assigned_by','recorded_by','actor_id']) ORDER BY 1 LOOP IF nullif(doc->>key,'') IS NOT NULL THEN uid:=(doc->>key)::uuid; PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,4917)); IF public.deletion_is_held(uid) THEN RAISE EXCEPTION 'Account privacy processing in progress'; END IF; END IF; END LOOP; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.guard_deletion_dependencies() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER deletion_dependency_fence BEFORE INSERT OR UPDATE ON public.appointments FOR EACH ROW EXECUTE FUNCTION public.guard_deletion_dependencies();
CREATE TRIGGER deletion_dependency_fence BEFORE INSERT OR UPDATE ON public.case_records FOR EACH ROW EXECUTE FUNCTION public.guard_deletion_dependencies();
CREATE TRIGGER deletion_dependency_fence BEFORE INSERT OR UPDATE ON public.prescriptions FOR EACH ROW EXECUTE FUNCTION public.guard_deletion_dependencies();
CREATE TRIGGER deletion_dependency_fence BEFORE INSERT OR UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.guard_deletion_dependencies();
CREATE TRIGGER deletion_dependency_fence BEFORE INSERT OR UPDATE ON public.payments FOR EACH ROW EXECUTE FUNCTION public.guard_deletion_dependencies();
CREATE TRIGGER deletion_dependency_fence BEFORE INSERT OR UPDATE ON public.clinical_assignments FOR EACH ROW EXECUTE FUNCTION public.guard_deletion_dependencies();
CREATE TRIGGER deletion_dependency_fence BEFORE INSERT OR UPDATE ON public.case_clinical_notes FOR EACH ROW EXECUTE FUNCTION public.guard_deletion_dependencies();
CREATE TRIGGER deletion_dependency_fence BEFORE INSERT OR UPDATE ON public.prescription_audit FOR EACH ROW EXECUTE FUNCTION public.guard_deletion_dependencies();
CREATE TRIGGER deletion_dependency_fence BEFORE INSERT OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.guard_deletion_dependencies();
CREATE POLICY clinical_assignment_identity_hold ON public.clinical_assignments AS RESTRICTIVE FOR ALL TO authenticated USING(NOT public.deletion_is_held(auth.uid())) WITH CHECK(NOT public.deletion_is_held(auth.uid()));
CREATE POLICY clinical_note_identity_hold ON public.case_clinical_notes AS RESTRICTIVE FOR ALL TO authenticated USING(NOT public.deletion_is_held(auth.uid())) WITH CHECK(NOT public.deletion_is_held(auth.uid()));
CREATE POLICY report_owner_identity_hold ON storage.objects AS RESTRICTIVE FOR ALL TO authenticated USING(bucket_id<>'patient-reports' OR (NOT public.deletion_is_held(auth.uid()) AND NOT public.deletion_is_held(((storage.foldername(name))[1])::uuid))) WITH CHECK(bucket_id<>'patient-reports' OR (NOT public.deletion_is_held(auth.uid()) AND NOT public.deletion_is_held(((storage.foldername(name))[1])::uuid)));
CREATE OR REPLACE FUNCTION public.reopen_data_deletion(_request uuid,_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_user::text,4917)); UPDATE public.account_deletion_requests SET processing_history=processing_history||jsonb_build_array(jsonb_build_object('completed_at',completed_at,'token',processing_token,'state',processing_state)),processing_state='pending',processing_token=NULL,completed_at=NULL,failure_code=NULL WHERE id=_request AND user_id=_user AND scope='data' AND processing_state='completed'; IF NOT FOUND THEN RAISE EXCEPTION 'No completed data deletion to reopen'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.reopen_data_deletion(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.reopen_data_deletion(uuid,uuid) TO service_role;